mapper.select:
SELECT
(is_visible = TRUE AND is_available = TRUE AND NOT EXISTS (
SELECT 1 FROM menu_set ms
JOIN menus cm ON ms.component_menu_id = cm.menu_id
WHERE ms.set_menu_id = #{menuId}
AND (cm.is_available = FALSE OR cm.is_visible = FALSE)
))
FROM menus
WHERE menu_id = #{menuId}

